-- LOCAL ISOLATED COPY ONLY. Never execute on production. No PK/unique added.
CREATE TABLE tbl_rawdata (FdDate DATE DEFAULT NULL,FcTime TIME DEFAULT NULL,FcCardNo VARCHAR(50) DEFAULT NULL,FcDirection VARCHAR(1) DEFAULT NULL,FcTermNo VARCHAR(3) DEFAULT NULL,FlFlag TINYINT DEFAULT NULL) ENGINE=InnoDB;
CREATE TABLE tbl_absen (FdDate DATETIME DEFAULT NULL,FcCardNo VARCHAR(50) DEFAULT NULL,FcDirection VARCHAR(1) DEFAULT NULL,FcTermNo VARCHAR(3) DEFAULT NULL) ENGINE=InnoDB;
