CREATE TABLE tbl_config (provider VARCHAR(30) PRIMARY KEY,client_id_encrypted TEXT NULL,client_secret_encrypted TEXT NULL,import_token_encrypted TEXT NULL,revision BIGINT NOT NULL DEFAULT 1,audit_history JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB COMMENT='mkm-talenta-config-v1';
